    scope_node_id: root,
    record_kind: "Task",
    title: filled(action.title, run.event, AUTOMATION_LIMITS.title, "Task title"),
    phase_code: action.phase_code,
    xyz: action.xyz,
    external_visibility: [],
    ...(action.due_at ? { due_at: action.due_at } : {}),
